// 通用存档读取：按 defaults 的类型（number / boolean）做容错
loadJson(key, defaults) {
  const out = Object.assign({}, defaults)
  try {
    const raw = storage.get(key, null)
    if (raw === null || raw === undefined || raw === '') return out
    const obj = typeof raw === 'string' ? JSON.parse(raw) : raw
    if (!obj) return out
    for (const k in defaults) {
      if (obj[k] === undefined) continue
      out[k] = typeof defaults[k] === 'boolean' ? !!obj[k] : Math.max(0, Number(obj[k]) | 0)
    }
  } catch (e) {
    /* 存档损坏则用默认值 */
  }
  return out
}

// 丹药在本局开局生效（每种同局只生效 1 颗）
applyPills() {
  const p = this.player
  if (this.pillStock.zhuji > 0) {
    this.pillStock.zhuji -= 1
    p.weaponLevel = Math.max(p.weaponLevel, 2)
    this.pillApplied.push(PILLS.zhuji.name)
  }
  if (this.pillStock.jinsui > 0) {
    this.pillStock.jinsui -= 1
    p.maxHp += 1
    p.hp += 1
    this.pillApplied.push(PILLS.jinsui.name)
  }
  if (this.pillStock.tianlei > 0) {
    this.pillStock.tianlei -= 1
    this.trumpCdMult = 0.8
    this.pillApplied.push(PILLS.tianlei.name)
  }
  if (this.pillApplied.length > 0) {
    storage.set(PILL_KEY, JSON.stringify(this.pillStock))
    this.pillFlash = 2.6
  }
}

// 炼丹：材料够则消耗并产出 1 颗丹药
brewPill(key) {
  const cfg = PILLS[key]
  if (!cfg) return false
  if ((this.herbStock[cfg.herb] || 0) < cfg.need) return false
  this.herbStock[cfg.herb] -= cfg.need
  this.pillStock[key] = (this.pillStock[key] || 0) + 1
  storage.set(HERB_KEY, JSON.stringify(this.herbStock))
  storage.set(PILL_KEY, JSON.stringify(this.pillStock))
  this.sfx.brew()
  return true
}

