// ---------- 秘境：灵草与限时 ----------

updateDungeonClock(dt) {
  const prev = Math.ceil(this.dungeonTime)
  this.dungeonTime -= dt
  const cur = Math.ceil(this.dungeonTime)
  // 最后 10 秒每秒滴答
  if (cur !== prev && cur <= 10 && cur > 0) this.sfx.tick()
  if (this.dungeonTime <= 0) {
    this.dungeonTime = 0
    this.settleDungeon()
  }
}

updateHerbs(dt) {
  for (const h of this.herbItems) {
    h.life -= dt
    if (h.life <= 0) h.dead = true
  }
  compact(this.herbItems)

  this.herbTimer -= dt
  if (this.herbTimer <= 0) {
    this.herbTimer = rand(1.4, 2.4)
    if (this.herbItems.length < 6) this.spawnHerb()
  }
}

spawnHerb() {
  // 按权重抽一种灵草
  const roll = Math.random()
  let acc = 0
  let key = HERB_KEYS[HERB_KEYS.length - 1]
  for (const k of HERB_KEYS) {
    acc += HERBS[k].weight
    if (roll < acc) {
      key = k
      break
    }
  }
  const cfg = HERBS[key]
  this.herbItems.push({
    key,
    x: rand(36, WORLD.W - 36),
    y: rand(110, WORLD.H - 130),
    r: cfg.r,
    life: cfg.life,
    maxLife: cfg.life,
    seed: rand(0, Math.PI * 2),
    dead: false,
  })
}

