// ---------- 渐变缓存（避免每帧 createLinearGradient）----------

const _grad = {} // { bg: { ctx, key, grad }, playerBody, playerFlame, bullet, bossBody, bossFlash, btnBlue }

function getBgGradient(ctx, key) {
  if (!_grad.bg || _grad.bg.key !== key || _grad.bg.ctx !== ctx) {
    const palette = typeof key === 'number' ? CHAPTERS[key].palette : DUNGEON_PALETTE
    const g = ctx.createLinearGradient(0, 0, 0, WORLD.H)
    g.addColorStop(0, palette[0])
    g.addColorStop(0.6, palette[1])
    g.addColorStop(1, palette[2])
    _grad.bg = { ctx, key, grad: g }
  }
  return _grad.bg.grad
}

