// 摘星 - 冒烟测试：模拟抖音小游戏运行环境，跑通主线/秘境/炼丹全流程
const path = require('path')
const ROOT = 'D:/Douin_game_development/pickstar/摘星'

// ---------- mock 平台 ----------
const store = {}
global.tt = {
  getSystemInfoSync: () => ({ pixelRatio: 2, windowWidth: 480, windowHeight: 720 }),
  getStorageSync: (k) => (store[k] === undefined ? '' : store[k]),
  setStorageSync: (k, v) => { store[k] = v },
  createCanvas: () => ({ width: 960, height: 1440, getContext: () => makeCtx() }),
  onTouchStart() {}, onTouchMove() {}, onTouchEnd() {}, onTouchCancel() {},
  onHide() {}, onShow() {},
}

function makeCtx() {
  const grad = { addColorStop() {} }
  const noop = () => {}
  return {
    canvas: { width: 960, height: 1440 },
    setTransform: noop, fillRect: noop, clearRect: noop,
    createLinearGradient: () => grad, createRadialGradient: () => grad,
    beginPath: noop, closePath: noop, moveTo: noop, lineTo: noop, arc: noop, arcTo: noop,
    ellipse: noop, quadraticCurveTo: noop, bezierCurveTo: noop, rect: noop,
    fill: noop, stroke: noop, save: noop, restore: noop, translate: noop, rotate: noop, scale: noop,
    fillText: noop, strokeText: noop, measureText: () => ({ width: 10 }),
    fillStyle: '', strokeStyle: '', lineWidth: 1, globalAlpha: 1, font: '', textAlign: '', textBaseline: '',
  }
}

const { ShooterEngine, WORLD, HERBS } = require(path.join(ROOT, 'src/engine.js'))
const { render } = require(path.join(ROOT, 'src/renderer.js'))
const { drawUi, hitButton } = require(path.join(ROOT, 'src/ui.js'))
const { SoundManager } = require(path.join(ROOT, 'src/sound.js'))

const fails = []
const ok = (cond, msg) => { if (!cond) fails.push(msg); else console.log('  ok  ' + msg) }

const sfx = new SoundManager()
const g = new ShooterEngine(sfx)
const ctx = makeCtx()

console.log('\n[1] 初始化')
ok(g.status === 'ready', '初始状态 ready')
ok(g.mode === 'main', '初始模式 main')
ok(typeof g.dao === 'number' && typeof g.herbStock.tianling === 'number', '存档字段已加载')

console.log('\n[2] 主线：选底牌 → 出阵')
g.enterTrumpSelect('main')
ok(g.status === 'trumpselect', '进入选牌界面')
const selBtns = ['ts-bixie', 'ts-qingzhu', 'ts-confirm', 'ts-skip', 'ts-back']
ok(selBtns.every((id) => findBtn(id)), '选牌界面按钮齐全')
g.toggleTrumpSelect('bixie')
g.toggleTrumpSelect('qingzhu') // 默认只有 1 个槽位，第二张应被拒绝
ok(g.tempSelectedTrumps.length === 1, '默认底牌槽位 = 1')
g.start()
ok(g.status === 'playing' && g.mode === 'main', '进入主线战斗')
ok(g.trumpCards.length === 1 && g.trumpCards[0] === 'bixie', '底牌已带入本局')
ok(findBtn('trump-0'), '底牌 HUD 按钮已生成')

console.log('\n[3] 底牌释放与冷却')
ok(g.activateTrump(0) === true, '辟邪神雷释放成功')
ok(g.trumpCd.bixie > 59 && g.trumpCd.bixie <= 60, '冷却 60 秒已写入')
ok(g.activateTrump(0) === false, '冷却中不可重复释放')

console.log('\n[4] 七元诀暂停冻结（原 bug）')
g.trumpCards = ['qiyuan']
g.trumpCd = { qiyuan: 0 }
g.activateTrump(0)
const before = g.doubleDamageTimer
g.togglePause()
for (let i = 0; i < 120; i++) g.update(1 / 60) // 暂停中推进 2 秒
ok(Math.abs(g.doubleDamageTimer - before) < 1e-6, '暂停期间伤害翻倍计时被冻结')
g.togglePause()
for (let i = 0; i < 60; i++) g.update(1 / 60)
ok(g.doubleDamageTimer < before - 0.9, '恢复后伤害翻倍正常倒计时')

console.log('\n[5] 主线跑 40 秒不崩')
g.player.invincibleUntil = Date.now() + 1e9
for (let i = 0; i < 2400; i++) { g.update(1 / 60); if (i % 60 === 0) render(ctx, g) }
ok(true, '主线 40 秒模拟无异常')
ok(g.chapterIdx >= 0, '境界推进逻辑存活，当前 chapterIdx=' + g.chapterIdx)

console.log('\n[6] 秘境：进入与限时结算')
g.enterTrumpSelect('blood')
ok(g.pendingMode === 'blood', 'pendingMode 已切到 blood')
g.start()
ok(g.mode === 'blood' && g.status === 'playing', '进入血色禁地')
ok(Math.abs(g.dungeonTime - 90) < 0.001, '限时 90 秒')
g.player.invincibleUntil = Date.now() + 1e9
let sawHerb = false
for (let i = 0; i < 6000 && g.status === 'playing'; i++) {
  g.update(1 / 60)
  if (g.herbItems.length > 0) sawHerb = true
  // 模拟玩家满场移动去采草
  g.setTouch(120 + (i % 240), 300 + (i % 300), true)
  if (i % 120 === 0) render(ctx, g)
}
ok(sawHerb, '秘境中刷出了灵草')
ok(g.status === 'dungeonsettle', '90 秒到点自动结算，状态=' + g.status)
ok(g.dungeonResult !== null, '结算数据已生成')
const r = g.dungeonResult
console.log('      采集分 ' + r.score + ' / 灵草 ' + r.count + ' 株 / 道行 +' + r.dao + ' / 首通 ' + r.firstClear)
ok(r.firstClear === true, '首次通关标记正确')
ok(g.clearRecord.blood === true, '首通记录已落盘')
ok(r.dao >= 5, '首通道行奖励 >= 5')

console.log('\n[7] 炼丹')
g.herbStock = { tianling: 0, nichang: 0, jinling: 0 }
ok(g.brewPill('zhuji') === false, '材料不足时无法炼制')
g.herbStock = { tianling: 3, nichang: 0, jinling: 0 }
ok(g.brewPill('zhuji') === true, '3 天灵果炼出筑基丹')
ok(g.pillStock.zhuji === 1, '丹药入库 1 颗')
ok(g.herbStock.tianling === 0, '材料已扣除')
ok(JSON.parse(store['zhaixing-pills']).zhuji === 1, '丹药存档已持久化')

console.log('\n[8] 丹药下局生效')
g.herbStock = { tianling: 0, nichang: 3, jinling: 3 }
g.brewPill('jinsui')
g.brewPill('tianlei')
g.toReady()
g.enterTrumpSelect('main')
g.start()
ok(g.player.weaponLevel >= 2, '筑基丹 → 开局剑诀 Lv.2')
ok(g.player.maxHp === 4, '金髓丹 → 开局 +1 命')
ok(g.trumpCdMult === 0.8, '天雷子 → 底牌冷却 -20%')
ok(g.pillApplied.length === 3, '三种丹药均记录生效')
ok(g.pillStock.zhuji === 0, '丹药已被消耗')
g.trumpCards = ['bixie']
g.trumpCd = { bixie: 0 }
g.activateTrump(0)
ok(Math.abs(g.trumpCd.bixie - 48) < 0.01, '冷却实际变为 48 秒')

console.log('\n[9] 全部界面渲染不崩')
const states = ['ready', 'playing', 'paused', 'over', 'upgrade', 'trumpselect', 'dungeonselect', 'alchemy', 'dungeonsettle']
g.dungeonResult = g.dungeonResult || { mode: 'blood', score: 300, dao: 8, firstClear: true, count: 9, bag: { tianling: 1, nichang: 3, jinling: 5 } }
for (const s of states) {
  g.status = s
  try {
    render(ctx, g)
    drawUi(ctx, g, false)
    console.log('  ok  ' + s + ' 渲染通过')
  } catch (e) {
    fails.push(s + ' 渲染失败: ' + e.message)
  }
}

console.log('\n[10] 触摸命中')
g.status = 'ready'
ok(hitButton(g, 240, 379) === 'start', 'ready 开始按钮命中')
ok(hitButton(g, 92, 447) === 'upgrade', 'ready 道行按钮命中')
ok(hitButton(g, 240, 447) === 'dungeon', 'ready 秘境按钮命中')
ok(hitButton(g, 388, 447) === 'alchemy', 'ready 丹房按钮命中')

function findBtn(id) {
  const { hitButton } = require(path.join(ROOT, 'src/ui.js'))
  // 遍历状态找按钮：直接用 getButtons 无法访问，改为扫描像素点
  const g2 = g
  const prev = g2.status
  const probe = (st) => {
    g2.status = st
    for (let y = 0; y < 720; y += 4) for (let x = 0; x < 480; x += 4) if (hitButton(g2, x, y) === id) return true
    return false
  }
  const found = probe('trumpselect') || probe('playing')
  g2.status = prev
  return found
}

console.log('\n=========================================')
if (fails.length === 0) {
  console.log('全部通过 ✅')
} else {
  console.log('失败 ' + fails.length + ' 项：')
  fails.forEach((f) => console.log('  ✗ ' + f))
  process.exitCode = 1
}

