killEnemy(e, giveScore = true) {
  e.dead = true
  // 秘境只认采集分：击杀不涨分、不叠连斩，逼玩家冒险去捡草
  const scoring = giveScore && this.mode === 'main'
  if (scoring) {
    // 连斩加成：每连斩 +10% 修为，上限 2x（10 连斩）
    this.combo += 1
    this.comboTimer = 3.0
    const mult = 1 + Math.min(this.combo - 1, 9) * 0.1
    this.score += Math.round(e.score * mult)
    // 高连斩时额外火花特效
    if (this.combo >= 5) {
      this.spark(e.x, e.y, '#fde047', 6)
    }
  }

  // 反杀检测：HP=1 且在无敌期内击杀（每局最多1次）
  if (giveScore && !this.counterKillUsed && this.player.hp === 1 && now() < this.player.invincibleUntil) {
    this.triggerCounterKill()
  }

