function collectButtons(st) {
  g.status = st
  const map = {}
  for (let y = 0; y < 720; y += 2) {
    for (let x = 0; x < 480; x += 2) {
      const id = hitButton(g, x, y)
      if (!id) continue
      const b = map[id] || (map[id] = { id, x0: 1e9, y0: 1e9, x1: -1, y1: -1 })
      if (x < b.x0) b.x0 = x
      if (x > b.x1) b.x1 = x
      if (y < b.y0) b.y0 = y
      if (y > b.y1) b.y1 = y
    }
  }
  return Object.values(map)
}
```
