gameOver() {
  // 秘境：生命归零提前结束，但已得收益照常结算
  if (this.dungeonCfg) {
    this.settleDungeon(false)
    return
  }
  this.status = 'over'
  this.combo = 0
  this.comboTimer = 0
  this.resetTrumps()
  if (this.score > this.best) {
    this.best = this.score
    storage.set(BEST_KEY, String(this.best))
  }
  // 道行结算：每 1000 修为 = 1 道行
  this.lastRunDao = Math.floor(this.score / 1000)
  this.dao += this.lastRunDao
  storage.set(DAO_KEY, String(this.dao))
  this.sfx.gameOver()
  this.explode(this.player.x, this.player.y, '#7dd3fc', 42)
  this.shake = 14
}

// 秘境道行：按各自玩法的主导产出折算，保证四种秘境收益同量级（单局 5~12）
calcDungeonDao(win) {
  const cfg = this.dungeonCfg
  if (!cfg) return 0
  switch (cfg.goal) {
    case 'collect':
      // 采集分密度远低于主线修为，按 100:1 折算
      return Math.floor(this.score / 100)
    case 'bossrush':
      return this.bossCleared * 4
    case 'seals':
      return this.seals.filter((s) => s.dead).length * 3
    case 'escort':
      return win ? 8 : 3
  }
  return 0
}

// 结算面板的明细行（四种秘境共用一套渲染）
dungeonSummary() {
  const cfg = this.dungeonCfg
  if (!cfg) return []
  switch (cfg.goal) {
    case 'collect':
      return HERB_KEYS.map((k) => ({ label: HERBS[k].name, value: '×' + this.herbBag[k], color: HERBS[k].color }))
    case 'bossrush':
      return [{ label: '击破魔物', value: this.bossCleared + ' / ' + cfg.waves, color: cfg.color }]
    case 'seals':
      return [{ label: '破除阵眼', value: this.seals.filter((s) => s.dead).length + ' / ' + cfg.seals, color: cfg.color }]
    case 'escort':
      return [{ label: '灵舟余量', value: Math.max(0, this.ship ? Math.ceil(this.ship.hp) : 0) + ' / ' + cfg.shipHp, color: cfg.color }]
  }
  return []
}

// 秘境结算：道行 + 灵草入库 + 首通记录
settleDungeon(win) {
  if (this.dungeonDone) return
  this.dungeonDone = true
  this.status = 'dungeonsettle'
  this.combo = 0
  this.comboTimer = 0
  this.resetTrumps()

  const cfg = this.dungeonCfg
  const firstClear = !!win && !this.clearRecord[this.mode]
  if (firstClear) this.clearRecord[this.mode] = true

  const daoGain = this.calcDungeonDao(win) + (firstClear ? 5 : 0)
  this.lastRunDao = daoGain
  this.dao += daoGain

  for (const k of HERB_KEYS) this.herbStock[k] = (this.herbStock[k] || 0) + this.herbBag[k]

  storage.set(DAO_KEY, String(this.dao))
  storage.set(HERB_KEY, JSON.stringify(this.herbStock))
  storage.set(CLEAR_KEY, JSON.stringify(this.clearRecord))

  let count = 0
  for (const k of HERB_KEYS) count += this.herbBag[k]
  this.dungeonResult = {
    mode: this.mode,
    name: cfg ? cfg.name : '',
    win: !!win,
    score: this.score,
    dao: daoGain,
    firstClear,
    count,
    bag: Object.assign({}, this.herbBag),
    lines: this.dungeonSummary(),
  }

  this.sfx.dungeonClear(!!win)
  this.explode(this.player.x, this.player.y, '#fbbf24', 36)
  this.shake = 10
}

