// ---------- 秘境：通用框架 ----------

// 初始化秘境专属实体
initDungeon() {
  const cfg = this.dungeonCfg
  if (cfg.goal === 'seals') this.spawnSeals(cfg.seals)
  else if (cfg.goal === 'escort') {
    this.ship = {
      x: WORLD.W / 2,
      y: WORLD.H - 96,
      w: 88,
      h: 56,
      hp: cfg.shipHp,
      maxHp: cfg.shipHp,
      dir: 1,
      flashUntil: 0,
    }
  } else if (cfg.goal === 'bossrush') {
    this.spawnBossWave()
  }
}

updateDungeon(dt) {
  const cfg = this.dungeonCfg

  // 限时倒计时（bossrush 用波数控制，dur = 0 不计时）
  if (cfg.dur > 0) {
    const prev = Math.ceil(this.dungeonTime)
    this.dungeonTime -= dt
    const cur = Math.ceil(this.dungeonTime)
    // 最后 10 秒每秒滴答
    if (cur !== prev && cur <= 10 && cur > 0) this.sfx.tick()
    if (this.dungeonTime <= 0) {
      this.dungeonTime = 0
      // 守护类限时撑满即通关，其余为限时结束
      this.settleDungeon(cfg.goal === 'escort')
      return
    }
  }

  switch (cfg.goal) {
    case 'collect':
      this.updateSpawning(dt)
      this.updateHerbs(dt)
      break
    case 'bossrush':
      // 无小怪，逐头登场
      if (!this.bossAlive() && this.bossWave < cfg.waves) {
        this.bossRespawnTimer -= dt
        if (this.bossRespawnTimer <= 0) this.spawnBossWave()
      }
      break
    case 'seals':
      this.updateSpawning(dt)
      this.updateSeals(dt)
      break
    case 'escort':
      this.updateSpawning(dt)
      this.updateShip(dt)
      break
  }
}

// ---------- 秘境 · 采集 ----------

updateHerbs(dt) {
  for (const h of this.herbItems) {
    h.life -= dt
    if (h.life <= 0) h.dead = true
  }
  compact(this.herbItems)

  this.herbTimer -= dt
  if (this.herbTimer <= 0) {
    this.herbTimer = rand(1.4, 2.4)
    if (this.herbItems.length < 6) this.spawnHerb()
  }
}

spawnHerb() {
  // 按权重抽一种灵草
  const roll = Math.random()
  let acc = 0
  let key = HERB_KEYS[HERB_KEYS.length - 1]
  for (const k of HERB_KEYS) {
    acc += HERBS[k].weight
    if (roll < acc) {
      key = k
      break
    }
  }
  const cfg = HERBS[key]
  this.herbItems.push({
    key,
    x: rand(36, WORLD.W - 36),
    y: rand(110, WORLD.H - 130),
    r: cfg.r,
    life: cfg.life,
    maxLife: cfg.life,
    seed: rand(0, Math.PI * 2),
    dead: false,
  })
}

// ---------- 秘境 · 阵眼（虚天殿） ----------

spawnSeals(n) {
  const pts = [
    [WORLD.W * 0.25, 200],
    [WORLD.W * 0.75, 200],
    [WORLD.W * 0.25, 370],
    [WORLD.W * 0.75, 370],
  ]
  this.seals = []
  for (let i = 0; i < n; i++) {
    const p = pts[i % pts.length]
    this.seals.push({
      x: p[0],
      y: p[1],
      r: 34,
      hp: 26,
      maxHp: 26,
      fireTimer: 2.2 + i * 0.6,
      seed: i * 1.7,
      flashUntil: 0,
      dead: false,
    })
  }
}

updateSeals(dt) {
  const t = now()
  let alive = 0
  for (const s of this.seals) {
    if (s.dead) continue
    alive++
    if (s.flashUntil < t) s.flashUntil = 0
    s.fireTimer -= dt
    if (s.fireTimer <= 0) {
      s.fireTimer = 3.4
      // 环形剑气，留一个缺口
      const n = 10
      const gap = Math.floor(rand(0, n))
      for (let i = 0; i < n; i++) {
        if (i === gap) continue
        const ang = (i / n) * Math.PI * 2
        this.bullets.push({
          x: s.x,
          y: s.y,
          vx: Math.cos(ang) * 95,
          vy: Math.sin(ang) * 95,
          r: 5,
          damage: 1,
          from: 'enemy',
          kind: 'seal',
        })
      }
    }
  }
  // 阵眼尽破 → 通关
  if (alive === 0) this.settleDungeon(true)
}

// ---------- 秘境 · 灵舟（乱星海） ----------

updateShip(dt) {
  const s = this.ship
  if (!s) return
  s.x += s.dir * 30 * dt
  if (s.x < 90) {
    s.x = 90
    s.dir = 1
  } else if (s.x > WORLD.W - 90) {
    s.x = WORLD.W - 90
    s.dir = -1
  }
}

damageShip(n) {
  const s = this.ship
  if (!s || s.hp <= 0) return
  s.hp -= n
  s.flashUntil = now() + 140
  this.shake = Math.max(this.shake, 3)
  if (s.hp <= 0) {
    s.hp = 0
    this.explode(s.x, s.y, '#22d3ee', 40)
    this.settleDungeon(false)
  }
}

// ---------- 秘境 · 魔物连战（坠魔谷） ----------

spawnBossWave() {
  const cfg = this.dungeonCfg
  this.bossWave += 1
  this.bossRespawnTimer = 1.8
  this.spawnBoss({
    hpScale: 1 + (this.bossWave - 1) * 0.35,
    color: cfg.color,
    name: this.bossWave >= cfg.waves ? '魔道老祖' : '魔物 ' + this.bossWave,
  })
}

