handleCollisions() {
  const t = now()
  const p = this.player
  const dmgMult = this.doubleDamageTimer > 0 ? 2 : 1

  for (const b of this.bullets) {
    if (b.from !== 'player' || b.dead) continue
    for (const e of this.enemies) {
      if (e.dead) continue
      if (this.hit({ x: b.x, y: b.y, w: b.r * 2, h: b.r * 2 + 8 }, e)) {
        b.dead = true
        e.hp -= b.damage * dmgMult
        e.flashUntil = t + 80
        this.spark(b.x, b.y - 4, '#fde68a', 4)
        if (e.hp <= 0) this.killEnemy(e)
        break
      }
    }
  }

  if (t > p.invincibleUntil) {
    const pb = { x: p.x, y: p.y, w: p.w * 0.5, h: p.h * 0.5 }
    for (const e of this.enemies) {
      if (e.dead) continue
      if (this.hit(pb, e)) {
        if (e.type !== 'boss') this.killEnemy(e, false)
        this.damagePlayer()
        break
      }
    }
  }
  if (t > p.invincibleUntil && this.status === 'playing') {
    for (const b of this.bullets) {
      if (b.from !== 'enemy' || b.dead) continue
      if (this.hit({ x: b.x, y: b.y, w: b.r * 2, h: b.r * 2 }, { x: p.x, y: p.y, w: p.w * 0.5, h: p.h * 0.5 })) {
        b.dead = true
        this.damagePlayer()
        break
      }
    }
  }

  for (const u of this.powerups) {
    if (u.dead) continue
    if (this.hit({ x: u.x, y: u.y, w: 30, h: 30 }, p)) {
      u.dead = true
      this.applyPowerup(u.kind)
    }
  }

  // 秘境灵草采集：贴近即拾取（弹幕不会摧毁灵草，必须玩家肉身穿过）
  if (this.mode !== 'main') {
    for (const h of this.herbItems) {
      if (h.dead) continue
      const dx = h.x - p.x
      const dy = h.y - p.y
      const reach = h.r + 22
      if (dx * dx + dy * dy < reach * reach) {
        h.dead = true
        this.herbBag[h.key] += 1
        this.score += HERBS[h.key].score
        this.sfx.collect()
        this.spark(h.x, h.y, HERBS[h.key].color, 10)
      }
    }
    compact(this.herbItems)
  }

  compact(this.bullets)
  compact(this.enemies)
  compact(this.powerups)
}

