// 爆炸与火花共用同一套粒子发射
emit(x, y, count, opt) {
  const o = opt || {}
  const spread = o.spread === undefined ? Math.PI * 2 : o.spread
  const base = o.base === undefined ? 0 : o.base
  const [sMin, sMax] = o.speed || [40, 260]
  const [lMin, lMax] = o.life || [0.3, 0.8]
  const [zMin, zMax] = o.size || [1.5, 4.5]
  for (let i = 0; i < count; i++) {
    const ang = base + rand(-spread / 2, spread / 2)
    const sp = rand(sMin, sMax)
    this.particles.push({
      x,
      y,
      vx: Math.cos(ang) * sp,
      vy: Math.sin(ang) * sp + (o.gravity === undefined ? -40 : o.gravity),
      life: rand(lMin, lMax),
      maxLife: lMax,
      size: rand(zMin, zMax),
      color: o.tint && Math.random() < 0.3 ? o.tint : o.color,
    })
  }
}

// 击杀爆炸：全向飞散
