Let me refactor the gradient cache first.

Current:
```js
const _grad = {}
function getBgGradient(ctx, key) {...}
function getPlayerBodyGradient(ctx) {
  if (!_grad.playerBody || _grad.playerBody.ctx !== ctx) {
    const g = ctx.createLinearGradient(0, -20, 0, 16)
    ...
    _grad.playerBody = { ctx, grad: g }
  }
  return _grad.playerBody.grad
}
... ×4 more
```

Replace with:
```js
const _grad = {}

// 渐变缓存：同一 ctx 下只创建一次（小游戏每帧重建渐变会掉帧）
function cachedGradient(key, build) {
  const c = _grad[key]
  if (c && c.ctx === _cacheCtx) return c.grad
  const grad = build()
  _grad[key] = { ctx: _cacheCtx, grad }
  return grad
}
```
Hmm needs ctx. Simpler:

```js
function cachedGradient(ctx, key, build) {
  const c = _grad[key]
  if (c && c.ctx === ctx) return c.grad
  const grad = build(ctx)
  _grad[key] = { ctx, grad }
  return grad
}
```

Then:
```js
const getBgGradient = (ctx, key) => cachedGradient(ctx, 'bg:' + key, (c) => {
  const palette = typeof key === 'number' ? CHAPTERS[key].palette : DUNGEON_PALETTE[key]
  const g = c.createLinearGradient(0, 0, 0, WORLD.H)
