// 摘星 - Canvas 渲染器（矢量绘制，无素材依赖）

const { WORLD, CHAPTERS, HERBS } = require('./engine.js')
const { now } = require('./platform.js')

// ---------- 渐变缓存（避免每帧 createLinearGradient）----------

const _grad = {}

// 同一 ctx 下同 key 的渐变只创建一次；原来 5 个 getXxxGradient 各抄了一遍这段逻辑
function cachedGradient(ctx, key, build) {
  const c = _grad[key]
  if (c && c.ctx === ctx) return c.grad
  const grad = build(ctx)
  _grad[key] = { ctx, grad }
  return grad
}

function getBgGradient(ctx, palette) {
  return cachedGradient(ctx, 'bg:' + palette[0], (c) => {
    const g = c.createLinearGradient(0, 0, 0, WORLD.H)
    g.addColorStop(0, palette[0])
    g.addColorStop(0.6, palette[1])
    g.addColorStop(1, palette[2])
    return g
  })
}

function getPlayerBodyGradient(ctx) {
  return cachedGradient(ctx, 'playerBody', (c) => {
    const g = c.createLinearGradient(0, -20, 0, 16)
    g.addColorStop(0, '#bae6fd')
    g.addColorStop(0.4, '#38bdf8')
    g.addColorStop(1, '#1d4ed8')
    return g
  })
}

function getPlayerFlameGradient(ctx) {
