    // 4 张升级卡片，整张卡都是触摸区域
    const cardY = [120, 225, 330, 435]
    const ids = ['up-sword', 'up-hp', 'up-bomb', 'up-trump']
    for (let i = 0; i < 4; i++) {
      btns.push({ id: ids[i], x: 30, y: cardY[i], w: 420, h: 95 })
    }
    btns.push({ id: 'back', x: W / 2 - 110, y: 560, w: 220, h: 44 })
  } else if (g.status === 'trumpselect') {
    // 5 张底牌卡片
    for (let i = 0; i < TRUMP_KEYS.length; i++) {
      btns.push({ id: 'ts-' + TRUMP_KEYS[i], x: 30, y: 108 + i * 74, w: 420, h: 68 })
    }
    btns.push({ id: 'ts-confirm', x: W / 2 - 110, y: 496, w: 220, h: 44 })
    btns.push({ id: 'ts-skip', x: W / 2 - 70, y: 552, w: 140, h: 36 })
    btns.push({ id: 'ts-back', x: 14, y: 14, w: 62, h: 28 })
  } else if (g.status === 'dungeonselect') {
    btns.push({ id: 'dg-blood', x: 40, y: 180, w: 400, h: 112 })
    btns.push({ id: 'back', x: W / 2 - 110, y: 470, w: 220, h: 44 })
  } else if (g.status === 'alchemy') {
    for (let i = 0; i < PILL_KEYS.length; i++) {
      btns.push({ id: 'brew-' + PILL_KEYS[i], x: 30, y: 150 + i * 108, w: 420, h: 96 })
    }
    btns.push({ id: 'back', x: W / 2 - 110, y: 520, w: 220, h: 44 })
