Add `dungeonProgress(g)` helper function.

```js
// 秘境目标进度文案（四种玩法共用）
function dungeonProgress(g) {
  const cfg = g.dungeonCfg
  if (!cfg) return ''
  if (cfg.goal === 'collect') {
    let picked = 0
    for (const k of HERB_KEYS) picked += g.herbBag[k]
    return '灵草 ' + picked + ' 株'
  }
  if (cfg.goal === 'bossrush') return '魔物 ' + g.bossCleared + '/' + cfg.waves
  if (cfg.goal === 'seals') {
    let alive = 0
    for (const s of g.seals) if (!s.dead) alive++
    return '阵眼 ' + (cfg.seals - alive) + '/' + cfg.seals
  }
  if (cfg.goal === 'escort') return '灵舟 ' + Math.max(0, Math.ceil(g.ship ? g.ship.hp : 0))
  return ''
}
```

Place before drawHud or after. Function declaration hoisted, fine.

