// 摘星 - 冒烟测试：模拟抖音小游戏运行环境，跑通主线 + 四种秘境 + 炼丹全流程
const path = require('path')
const ROOT = 'D:/Douin_game_development/pickstar/摘星'

// ---------- mock 平台 ----------
const store = {}
global.tt = {
  getSystemInfoSync: () => ({ pixelRatio: 2, windowWidth: 480, windowHeight: 720 }),
  getStorageSync: (k) => (store[k] === undefined ? '' : store[k]),
  setStorageSync: (k, v) => { store[k] = v },
  createCanvas: () => ({ width: 960, height: 1440, getContext: () => makeCtx() }),
  onTouchStart() {}, onTouchMove() {}, onTouchEnd() {}, onTouchCancel() {},
  onHide() {}, onShow() {},
}

function makeCtx() {
  const grad = { addColorStop() {} }
  const noop = () => {}
  return {
    canvas: { width: 960, height: 1440 },
    setTransform: noop, fillRect: noop, clearRect: noop,
    createLinearGradient: () => grad, createRadialGradient: () => grad,
    beginPath: noop, closePath: noop, moveTo: noop, lineTo: noop, arc: noop, arcTo: noop,
    ellipse: noop, quadraticCurveTo: noop, bezierCurveTo: noop, rect: noop,
    fill: noop, stroke: noop, save: noop, restore: noop, translate: noop, rotate: noop, scale: noop,
    fillText: noop, strokeText: noop, measureText: () => ({ width: 10 }),
    fillStyle: '', strokeStyle: '', lineWidth: 1, globalAlpha: 1, font: '', textAlign: '', textBaseline: '',
  }
}

const { ShooterEngine, DUNGEONS, DUNGEON_KEYS } = require(path.join(ROOT, 'src/engine.js'))
const { render } = require(path.join(ROOT, 'src/renderer.js'))
const { drawUi, hitButton } = require(path.join(ROOT, 'src/ui.js'))
const { SoundManager } = require(path.join(ROOT, 'src/sound.js'))

const fails = []
const ok = (cond, msg) => { if (!cond) fails.push(msg); else console.log('  ok  ' + msg) }

const sfx = new SoundManager()
const g = new ShooterEngine(sfx)
const ctx = makeCtx()

function runFrames(n, hook) {
  for (let i = 0; i < n && g.status === 'playing'; i++) {
    g.update(1 / 60)
    if (hook) hook(i)
  }
}

// 秘境通用入口：选牌 → 出阵
function enterDungeon(key) {
  g.toReady()
  g.enterTrumpSelect(key)
  g.start()
}

console.log('\n[1] 初始化')
ok(g.status === 'ready', '初始状态 ready')
ok(g.mode === 'main', '初始模式 main')
ok(DUNGEON_KEYS.length === 4, '秘境配置 4 种：' + DUNGEON_KEYS.join('/'))
ok(typeof g.dao === 'number' && typeof g.herbStock.tianling === 'number', '存档字段已加载')

console.log('\n[2] 主线：选底牌 → 出阵')
g.enterTrumpSelect('main')
ok(g.status === 'trumpselect', '进入选牌界面')
ok(['ts-bixie', 'ts-qingzhu', 'ts-confirm', 'ts-skip', 'ts-back'].every((id) => findBtn(id, 'trumpselect')), '选牌界面按钮齐全')
g.toggleTrumpSelect('bixie')
g.toggleTrumpSelect('qingzhu') // 默认只有 1 个槽位
ok(g.tempSelectedTrumps.length === 1, '默认底牌槽位 = 1')
g.start()
ok(g.status === 'playing' && g.mode === 'main', '进入主线战斗')
ok(g.trumpCards.length === 1 && g.trumpCards[0] === 'bixie', '底牌已带入本局')
ok(findBtn('trump-0', 'playing'), '底牌 HUD 按钮已生成')

console.log('\n[3] 底牌释放与冷却')
ok(g.activateTrump(0) === true, '辟邪神雷释放成功')
ok(g.trumpCd.bixie > 59 && g.trumpCd.bixie <= 60, '冷却 60 秒已写入')
ok(g.activateTrump(0) === false, '冷却中不可重复释放')

console.log('\n[4] 七元诀暂停冻结')
g.trumpCards = ['qiyuan']
g.trumpCd = { qiyuan: 0 }
g.activateTrump(0)
const before = g.doubleDamageTimer
g.togglePause()
for (let i = 0; i < 120; i++) g.update(1 / 60)
ok(Math.abs(g.doubleDamageTimer - before) < 1e-6, '暂停期间伤害翻倍计时被冻结')
g.togglePause()
for (let i = 0; i < 60; i++) g.update(1 / 60)
ok(g.doubleDamageTimer < before - 0.9, '恢复后伤害翻倍正常倒计时')

console.log('\n[5] 主线跑 40 秒不崩')
