g.trumpCards = ['bixie', 'qingzhu', 'xutian']
for (const st of states) {
  const list = collectButtons(st)
  const oob = list.filter((b) => b.x0 < 0 || b.y0 < 0 || b.x1 >= 480 || b.y1 >= 720)
  let overlap = null
  for (let i = 0; i < list.length; i++) {
    for (let j = i + 1; j < list.length; j++) {
      const a = list[i], b = list[j]
      if (!(a.x1 < b.x0 || b.x1 < a.x0 || a.y1 < b.y0 || b.y1 < a.y0)) overlap = a.id + ' × ' + b.id
    }
  }
  if (oob.length === 0 && !overlap) console.log('  ok  ' + st + ' (' + list.length + ') ' + list.map((b) => b.id).join(', '))
  else fails.push(st + ' 布局问题: ' + (oob.length ? '越界 ' + oob.map((b) => b.id) : '重叠 ' + overlap))
}

