ok(hitButton(g, 240, 402) === 'dg-sea', '秘境列表第 4 项命中')

function collectButtons(st) {
  g.status = st
  const map = {}
  for (let y = 0; y < 720; y += 2) {
    for (let x = 0; x < 480; x += 2) {
      const id = hitButton(g, x, y)
      if (!id) continue
      const b = map[id] || (map[id] = { id, x0: 1e9, y0: 1e9, x1: -1, y1: -1 })
      if (x < b.x0) b.x0 = x
      if (x > b.x1) b.x1 = x
      if (y < b.y0) b.y0 = y
      if (y > b.y1) b.y1 = y
    }
  }
  return Object.keys(map).map((k) => map[k])
}

function findBtn(id, st) {
  const prev = g.status
  g.status = st
  let found = false
  for (let y = 0; y < 720 && !found; y += 4) {
    for (let x = 0; x < 480; x += 4) {
      if (hitButton(g, x, y) === id) { found = true; break }
    }
  }
  g.status = prev
  return found
}

console.log('\n=========================================')
if (fails.length === 0) {
  console.log('全部通过 ✅')
} else {
  console.log('失败 ' + fails.length + ' 项：')
  fails.forEach((f) => console.log('  ✗ ' + f))
  process.exitCode = 1
}

