**1. src/launch.js** (new)

```js
// 摘星 - 启动来源判定与抖音关键 API 接入
// 依据《抖音小游戏开发规范规则书》§2.4 / §4.1 / §4.2
//
// 三个概念必须分清：
//   直玩预启动  抖音在推荐流后台预加载游戏，用户还没点进来 —— 不能弹窗、不能算活跃
//   直玩点击启动 用户点了「立即去玩」，收到 feedEnter 才是真实用户
//   获客版      feed_game_channel = 2，全程禁止功能/提示/奖励弹窗

const FEED_SCENE_SUFFIX = '3041' // scene 后四位 3041 = 推荐流直玩场景
const REPORT_SCENE_ID = 7001     // 固定值：游戏加载完成、达到用户可交互状态
const CHANNEL_ACQUISITION = 2    // 获客用户
const CHANNEL_RETURNING = 1      // 复访用户
const POPUP_GUARD_MS = 5000      // §4.2：进入游戏 5 秒内禁止弹窗

function readOptions() {
  try {
    if (typeof tt !== 'undefined' && typeof tt.getLaunchOptionsSync === 'function') {
      return tt.getLaunchOptionsSync() || {}
    }
  } catch (err) {
    /* 低版本或异常，按普通启动处理 */
  }
  return {}
}

const opt = readOptions()
const query = opt.query || {}
const scene = opt.scene === undefined || opt.scene === null ? '' : String(opt.scene)
const channel = Number(query.feed_game_channel) || 0
const isFeed = scene.length >= 4 && scene.slice(-4) === FEED_SCENE_SUFFIX

const state = {
  scene,
  query,
  isFeed,
  channel,
  isAcquisition: isFeed && channel === CHANNEL_ACQUISITION,
  isReturning: isFeed && channel === CHANNEL_RETURNING,
  entered: false,     // 用户是否已真实进入（feedEnter / 首次触摸）
  enteredAt: 0,
  readyReported: false,
}

let enterCb = null

function markEntered(source) {
  if (state.entered) return
  state.entered = true
  state.enteredAt = Date.now()
  if (enterCb) enterCb(source || 'unknown')
}

function onEnter(cb) {
  if (typeof cb !== 'function') return
  if (state.entered) { cb('cached'); return }
  enterCb = cb
}

// 上报加载完成（§2.4 必接，未上报游戏不会在推荐流展示）
function reportReady() {
  if (state.readyReported) return
  state.readyReported = true
  try {
    if (typeof tt !== 'undefined' && typeof tt.reportScene === 'function') {
      tt.reportScene({ sceneId: REPORT_SCENE_ID })
    }
  } catch (err) { /* 非直玩环境或低版本，忽略 */ }
}

// 预览流进入/退出监听（规则书写作 tt.feedStatusChange，官方文档为 tt.onFeedStatusChange，两个都兜住）
function watchFeed(onExit) {
  const on = (typeof tt !== 'undefined') && (tt.onFeedStatusChange || tt.feedStatusChange)
  if (typeof on !== 'function') return false
  const handler = (res) => {
    const type = res && res.type
    if (type === 'feedEnter') markEntered('feed')
    else if (type === 'feedExit' && typeof onExit === 'function') onExit()
  }
  try {
    if (tt.onFeedStatusChange) tt.onFeedStatusChange(handler)
    else tt.feedStatusChange(handler)
    return true
  } catch (err) { return false }
}

// §4.2：5 秒内禁止弹窗；获客版全程禁止
function popupAllowed(elapsedMs) {
  if (state.isAcquisition) return false
  return elapsedMs >= POPUP_GUARD_MS
}

module.exports = { state, isFeed, isAcquisition, isReturning, markEntered, onEnter, reportReady, watchFeed, popupAllowed, POPUP_GUARD_MS }
```

Hmm, exporting both `state` and individual fields is redundant. Let me export a single `launch` object with getters. Simpler: export object with properties.

```js
const launch = {
  scene, query, channel, isFeed,
  isAcquisition: ...,
  isReturning: ...,
