// 摘星 - 启动来源判定与抖音关键 API 接入
// 依据《抖音小游戏开发规范规则书》§2.4 关键 API / §4.1 画面规范 / §4.2 弹窗规范
//
// 三个概念必须分清，混淆会直接导致直玩方案下线：
//   直玩预启动    抖音在推荐流后台预加载游戏，用户还没点进来 —— 不能弹窗、不算活跃
//   直玩点击启动  用户点了「立即去玩」，收到 feedEnter 才是真实用户
//   获客版        feed_game_channel = 2，全程禁止功能 / 提示 / 奖励弹窗

const FEED_SCENE_SUFFIX = '3041' // scene 后四位为 3041 即推荐流直玩场景
const REPORT_SCENE_ID = 7001 // 固定值：游戏加载完成、达到用户可交互状态
const CHANNEL_RETURNING = 1 // 复访用户
const CHANNEL_ACQUISITION = 2 // 获客用户
const POPUP_GUARD_MS = 5000 // §4.2：进入游戏 5 秒内禁止弹窗

// 启动参数：任何异常都退化为「普通启动」，不能因为取不到参数就白屏
function readOptions() {
  try {
    if (typeof tt !== 'undefined' && typeof tt.getLaunchOptionsSync === 'function') {
      return tt.getLaunchOptionsSync() || {}
    }
  } catch (err) {
    /* 低版本或非抖音环境，按普通启动处理 */
  }
  return {}
}

const opt = readOptions()
const query = opt.query || {}
const scene = opt.scene === undefined || opt.scene === null ? '' : String(opt.scene)
const channel = Number(query.feed_game_channel) || 0
const isFeed = scene.length >= 4 && scene.slice(-4) === FEED_SCENE_SUFFIX

// 用户是否已真实进入（feedEnter 或首次触摸）。预启动阶段恒为 false
let entered = false
let enteredAt = 0
let readyReported = false
let enterCb = null

function markEntered(source) {
  if (entered) return
  entered = true
  enteredAt = Date.now()
  if (typeof enterCb === 'function') enterCb(source || 'unknown')
}

function onEnter(cb) {
  if (typeof cb !== 'function') return
  if (entered) {
    cb('cached')
    return
  }
  enterCb = cb
}

// §2.4 必接：不上报加载完成，游戏不会出现在推荐流里
function reportReady() {
  if (readyReported) return
  readyReported = true
  try {
    if (typeof tt !== 'undefined' && typeof tt.reportScene === 'function') {
      tt.reportScene({ sceneId: REPORT_SCENE_ID })
    }
  } catch (err) {
    /* 非直玩环境或低版本，忽略 */
  }
}

// 预览流进入 / 退出监听。规则书写作 tt.feedStatusChange，官方文档为 tt.onFeedStatusChange，
// 两个名字都兜住；都不可用时返回 false，由调用方降级为「首次触摸即算进入」
function watchFeed(onExit) {
  const api =
    typeof tt === 'undefined'
      ? null
      : typeof tt.onFeedStatusChange === 'function'
      ? tt.onFeedStatusChange
      : typeof tt.feedStatusChange === 'function'
      ? tt.feedStatusChange
      : null
  if (!api) return false

  const handler = (res) => {
    const type = res && res.type
    if (type === 'feedEnter') {
      markEntered('feed')
    } else if (type === 'feedExit' && typeof onExit === 'function') {
      onExit()
    }
  }
  try {
    api.call(tt, handler)
    return true
  } catch (err) {
    return false
  }
}

// §4.2：获客版全程禁弹窗；其余情况进入游戏 5 秒后才允许
function popupAllowed(elapsedMs) {
  if (isFeed && channel === CHANNEL_ACQUISITION) return false
  return elapsedMs >= POPUP_GUARD_MS
}

module.exports = {
  scene,
  query,
  channel,
  isFeed,
  isAcquisition: isFeed && channel === CHANNEL_ACQUISITION,
  isReturning: isFeed && channel === CHANNEL_RETURNING,
  get entered() {
    return entered
  },
  get enteredAt() {
    return enteredAt
  },
  markEntered,
  onEnter,
  reportReady,
  watchFeed,
  popupAllowed,
  POPUP_GUARD_MS,
}

