const { render } = require('./src/renderer.js')
const { drawUi, hitButton } = require('./src/ui.js')
const { SoundManager } = require('./src/sound.js')
const launch = require('./src/launch.js')

const sound = new SoundManager()
const game = new ShooterEngine(sound)

const { canvas } = createGameCanvas()
const ctx = canvas.getContext('2d')
const transform = makeTransform(canvas, WORLD.W, WORLD.H)

// ---------- 推荐流直玩接入（规则书 §2.4 / §4.1 / §4.2） ----------

// 获客版全程禁止菜单类弹窗，直接开打
game.menuLocked = launch.isAcquisition

// 直玩启动：跳过主菜单直接进入实机玩法，满足 §4.1「直玩画面必须是实机核心玩法」
// 预启动阶段用户还没点进来，用自动巡航保证推荐流画面始终有动态，不至于是一张静图
if (launch.isFeed) {
  game.autopilot = true
  game.startDirect()
}

// feedEnter：用户真实进入，交回手动操作；feedExit：回推荐流，暂停避免后台挨打
launch.watchFeed(() => {
  if (game.status === 'playing') game.togglePause()
})
launch.onEnter(() => {
  game.autopilot = false
})

onStart(pos) {
  if (!pos) return
  // 低版本抖音没有 feedStatusChange，用首次触摸兜底判定「真实进入」
  launch.markEntered('touch')
  const btn = hitButton(game, pos.x, pos.y)
  touchOnButton = !!btn
  if (game.status === 'playing' && !btn) {
    game.setTouch(pos.x, pos.y, true)
  }
},

