// 主线：先选底牌，再出阵（获客版不允许内容确认弹窗，直接开打）
case 'start':
case 'restart':
  if (game.menuLocked) game.startDirect()
  else game.enterTrumpSelect('main')
  break
// 秘境：选完底牌直接进秘境
case 'dg-again':
  game.enterTrumpSelect(game.dungeonResult ? game.dungeonResult.mode : 'blood')
