let lastTs = now()
let firstFrameDone = false

function loop() {
  const ts = now()
  // 切后台回来时 ts 差值会很大，dt 上限 1/30 天然防跳帧
  const dt = Math.min((ts - lastTs) / 1000, 1 / 30)
  lastTs = ts

  game.update(dt)

  // 清屏（物理像素）
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  ctx.fillStyle = '#070b18'
  ctx.fillRect(0, 0, canvas.width, canvas.height)

  // 逻辑坐标系绘制
  ctx.setTransform(transform.scale, 0, 0, transform.scale, transform.offsetX, transform.offsetY)
  render(ctx, game)
  drawUi(ctx, game, sound.muted)

  // §2.4 必接：首帧画完、用户可交互时才上报加载完成，早报会被判为无效
  if (!firstFrameDone) {
    firstFrameDone = true
    launch.reportReady()
  }

  raf(loop)
}

