updatePlayer(dt) {
  const p = this.player
  if (this.touch.active) {
    // 手指位置上方偏移 70 逻辑像素，避免手指遮挡
    const tx = this.touch.x
    const ty = this.touch.y - 70
    const k = 1 - Math.pow(0.0001, dt)
    p.x += (tx - p.x) * k
    p.y += (ty - p.y) * k
  } else if (this.autopilot) {
    // 直玩预启动：无人操作时按正弦轨迹巡航，推荐流卡片上始终有实机动作
    this.demoT += dt
    const tx = WORLD.W / 2 + Math.sin(this.demoT * 1.1) * (WORLD.W * 0.28)
    const ty = WORLD.H - 180 + Math.cos(this.demoT * 0.8) * 62
    const k = 1 - Math.pow(0.002, dt)
    p.x += (tx - p.x) * k
    p.y += (ty - p.y) * k
  }
  p.x = clamp(p.x, p.w / 2 + 4, WORLD.W - p.w / 2 - 4)
  p.y = clamp(p.y, p.h / 2 + 4, WORLD.H - p.h / 2 - 4)

