  const sa = sysInfo.safeArea
  const top = sa && typeof sa.top === 'number' ? sa.top : sysInfo.statusBarHeight || 0
  if (!top) return 0
  return Math.max(0, (top * dpr - tr.offsetY) / tr.scale)
}

