// 摘星 - 广告位管理（Banner / 激励视频 / 插屏）
// 依据《抖音小游戏开发规范规则书》§3.2：
//   - 主场景禁止 Banner，只能放主菜单，底部居中，不遮挡按钮
//   - 激励视频必须明示、必须保留「不看广告」入口，关闭按钮 ≤3 秒
//   - 插屏：启动 30 秒内禁用，两次间隔 ≥60 秒，与激励视频间隔 ≥60 秒
//
// 设计要点：
//   - 广告位 ID 留空时整体降级为「无广告」，游戏照常运行
//   - 玩家可通过主菜单的 AD 开关随时关闭，选择持久化到本地

const { storage, sysInfo } = require('./platform.js')

// TODO: 在抖音开放平台「变现能力-广告位管理」申请后填入
const AD_UNITS = {
  banner: '',
  rewarded: '',
  interstitial: '',
}

const ENABLE_KEY = 'zhaixing-ads'
const LAUNCH_GUARD_MS = 30000 // 启动后 30 秒内不出插屏
const INTERSTITIAL_GAP_MS = 60000 // 两次插屏间隔
const REWARD_GAP_MS = 60000 // 插屏与激励视频间隔

const hasApi = (name) => typeof tt !== 'undefined' && typeof tt[name] === 'function'

class AdManager {
  constructor() {
    // 默认开启；玩家关掉后写 '0'，下次启动保持关闭
    this.enabled = storage.get(ENABLE_KEY, '1') !== '0'
    this.startedAt = Date.now()
    this.banner = null
    this.bannerVisible = false
    this.bannerHeight = 0
    this.rewarded = null
    this.rewardedLoading = false
    this.interstitial = null
    this.lastInterstitialAt = 0
    this.lastRewardAt = 0
    // 统计：既供埋点，也方便自查广告是否真的跑起来
    this.stats = { bannerShow: 0, rewardRequest: 0, rewardDone: 0, rewardSkip: 0, rewardFail: 0, interstitial: 0 }
  }

  // ---------- 开关 ----------

  setEnabled(on) {
    this.enabled = !!on
    storage.set(ENABLE_KEY, this.enabled ? '1' : '0')
    if (!this.enabled) {
      this.hideBanner()
      this.destroyInterstitial()
    }
    return this.enabled
  }

  toggle() {
    return this.setEnabled(!this.enabled)
  }

  // 是否有任何可用广告位
  get available() {
    return this.enabled && !!(AD_UNITS.banner || AD_UNITS.rewarded || AD_UNITS.interstitial)
  }

  // 激励视频是否可提供（开关打开 + 已配置 + 平台支持）
  get canReward() {
    return this.enabled && !!AD_UNITS.rewarded && hasApi('createRewardedVideoAd')
  }

  // ---------- Banner ----------

  ensureBanner() {
    if (this.banner || !this.enabled || !AD_UNITS.banner || !hasApi('createBannerAd')) return this.banner
    try {
      const w = Math.max(300, Math.min(sysInfo.windowWidth, 750))
      const ad = tt.createBannerAd({
        adUnitId: AD_UNITS.banner,
        style: { left: (sysInfo.windowWidth - w) / 2, top: sysInfo.windowHeight - 100, width: w },
      })
      // 高度要等 onResize 才知道，拿到后再贴底，避免遮住游戏内容
      ad.onResize((size) => {
        this.bannerHeight = (size && size.height) || 0
        if (this.banner) this.banner.style.top = sysInfo.windowHeight - this.bannerHeight
      })
      ad.onError(() => {
        this.bannerVisible = false
      })
      this.banner = ad
    } catch (err) {
      this.banner = null
    }
    return this.banner
  }

  showBanner() {
    if (!this.enabled || this.bannerVisible) return false
    const ad = this.ensureBanner()
    if (!ad) return false
    try {
      ad.show()
      this.bannerVisible = true
      this.stats.bannerShow += 1
      return true
    } catch (err) {
      this.bannerVisible = false
      return false
    }
  }

  hideBanner() {
    if (!this.banner || !this.bannerVisible) {
      this.bannerVisible = false
      return
    }
    try {
      this.banner.hide()
    } catch (err) {
      /* 忽略 */
    }
    this.bannerVisible = false
  }

  // ---------- 激励视频 ----------

  ensureRewarded() {
    if (this.rewarded || !this.canReward) return this.rewarded
    try {
      this.rewarded = tt.createRewardedVideoAd({ adUnitId: AD_UNITS.rewarded })
    } catch (err) {
      this.rewarded = null
    }
    return this.rewarded
  }

  // 拉取激励视频。onDone(completed)：completed=true 表示完整看完，可发奖
  showRewarded(onDone) {
    const done = typeof onDone === 'function' ? onDone : () => {}
    const ad = this.ensureRewarded()
    if (!ad) {
      this.stats.rewardFail += 1
      done(false, 'unavailable')
      return
    }

    this.stats.rewardRequest += 1
    let settled = false
    const finish = (completed, reason) => {
      if (settled) return
      settled = true
      if (completed) {
        this.stats.rewardDone += 1
        this.lastRewardAt = Date.now()
      } else if (reason === 'abort') {
        this.stats.rewardSkip += 1
      } else {
        this.stats.rewardFail += 1
      }
      done(completed, reason || '')
    }

    // onClose 只挂一次；用闭包变量指向当前这次请求的 finish
    if (!ad.__bound) {
      ad.__bound = true
      ad.__finish = null
      ad.onClose((res) => {
        const f = ad.__finish
        ad.__finish = null
        if (f) f(!!(res && res.isEnded), res && res.isEnded ? 'ended' : 'abort')
      })
      ad.onError(() => {
        const f = ad.__finish
        ad.__finish = null
        if (f) f(false, 'error')
      })
    }
    ad.__finish = finish

    try {
      ad.load()
        .then(() => ad.show())
        .catch(() => finish(false, 'error'))
    } catch (err) {
      finish(false, 'error')
    }
  }

  // ---------- 插屏 ----------

  destroyInterstitial() {
    if (!this.interstitial) return
    try {
      if (typeof this.interstitial.destroy === 'function') this.interstitial.destroy()
    } catch (err) {
      /* 忽略 */
    }
    this.interstitial = null
  }

  // 规则闸门：启动 30 秒 + 两次插屏 60 秒 + 与激励视频 60 秒
  interstitialAllowed() {
    if (!this.enabled || !AD_UNITS.interstitial || !hasApi('createInterstitialAd')) return false
    const t = Date.now()
    if (t - this.startedAt < LAUNCH_GUARD_MS) return false
    if (this.lastInterstitialAt && t - this.lastInterstitialAt < INTERSTITIAL_GAP_MS) return false
    if (this.lastRewardAt && t - this.lastRewardAt < REWARD_GAP_MS) return false
    return true
  }

  maybeInterstitial() {
    if (!this.interstitialAllowed()) return false
    try {
      if (!this.interstitial) this.interstitial = tt.createInterstitialAd({ adUnitId: AD_UNITS.interstitial })
      const ad = this.interstitial
      ad.load()
        .then(() => ad.show())
        .catch(() => {})
      this.lastInterstitialAt = Date.now()
      this.stats.interstitial += 1
      return true
    } catch (err) {
      return false
    }
  }
}

module.exports = { AdManager, AD_UNITS }

// 摘星 - 埋点
// 走 tt.reportAnalytics。事件名需先在抖音开放平台「数据分析 - 自定义分析」注册，
// 未注册的事件平台会静默丢弃 —— 所以这里所有调用都必须容错，不能影响游戏。
//
// 字段规范：只允许 string / number，单事件字段数建议 ≤ 10。

const PREFIX = 'zx_' // 统一前缀，方便后台筛选

let sent = 0
const onceFlags = {}

function available() {
  return typeof tt !== 'undefined' && typeof tt.reportAnalytics === 'function'
}

// 清洗参数：布尔转 0/1，其余非法类型丢弃
function clean(data) {
  const out = {}
  if (!data) return out
  for (const k in data) {
    const v = data[k]
    if (typeof v === 'number' && isFinite(v)) out[k] = Math.round(v * 100) / 100
    else if (typeof v === 'string') out[k] = v.slice(0, 60)
    else if (typeof v === 'boolean') out[k] = v ? 1 : 0
  }
  return out
}

function send(name, data) {
  if (!name) return false
  try {
    if (!available()) return false
    tt.reportAnalytics(PREFIX + name, clean(data))
    sent += 1
    return true
  } catch (err) {
    return false
  }
}

// 每个会话只报一次（如 app_launch）
function once(name, data) {
  if (onceFlags[name]) return false
  onceFlags[name] = true
  return send(name, data)
}

// 局内计时：从开局到结算的秒数
function duration(startTs) {
  if (!startTs) return 0
  return Math.max(0, Math.round((Date.now() - startTs) / 1000))
}

function count() {
  return sent
}

module.exports = { send, once, duration, count, PREFIX }

