const store = {}
let reportSceneCalls = []
let feedHandler = null
let launchOptions = { scene: '011001', query: {} } // 默认：普通启动，非直玩
let vibes = []
let analytics = []
let rewardedMode = 'ended' // ended | abort | error

global.tt = {
  getSystemInfoSync: () => ({ pixelRatio: 2, windowWidth: 480, windowHeight: 720 }),
  getStorageSync: (k) => (store[k] === undefined ? '' : store[k]),
  setStorageSync: (k, v) => { store[k] = v },
  createCanvas: () => ({ width: 960, height: 1440, getContext: () => makeCtx() }),
  onTouchStart() {}, onTouchMove() {}, onTouchEnd() {}, onTouchCancel() {},
  onHide() {}, onShow() {},
  // 规则书 §2.4 三个必接 API
  getLaunchOptionsSync: () => launchOptions,
  reportScene: (o) => { reportSceneCalls.push(o) },
  onFeedStatusChange: (cb) => { feedHandler = cb },
  // 设备能力
  vibrateShort: (o) => { vibes.push(o.type) },
  setKeepScreenOn() {},
  // 埋点
  reportAnalytics: (name, data) => { analytics.push({ name, data }) },
  // 广告位
  createBannerAd: (o) => {
    const ad = {
      style: o.style,
      shown: false,
      onResize(cb) { ad._resize = cb; if (cb) cb({ width: o.style.width, height: 75 }) },
      onError(cb) { ad._err = cb },
      show() { ad.shown = true },
      hide() { ad.shown = false },
    }
    return ad
  },
  createRewardedVideoAd: () => {
    const ad = {
      onClose(cb) { ad._close = cb },
      onError(cb) { ad._err = cb },
      load: () => Promise.resolve(),
      show: () => {
        // 模拟用户看完 / 中途关闭 / 加载失败
        if (rewardedMode === 'ended') ad._close && ad._close({ isEnded: true })
        else if (rewardedMode === 'abort') ad._close && ad._close({ isEnded: false })
        else ad._err && ad._err({ errCode: -1 })
        return Promise.resolve()
      },
    }
    return ad
  },
  createInterstitialAd: () => {
    const ad = {
      shown: 0,
      onError() {},
      load: () => Promise.resolve(),
      show: () => { ad.shown += 1; return Promise.resolve() },
      destroy() {},
    }
    return ad
  },
}

