applyPills() {
  const key = this.pillQueue
  const cfg = PILLS[key]
  if (!cfg || (this.pillStock[key] || 0) <= 0) {
    if (this.pillQueue) this.setPillQueue('')
    return
  }
  const p = this.player
  if (key === 'zhuji') this.pillShield = 1 // 本局首次受伤不掉剑诀
  else if (key === 'jinsui') {
    p.maxHp += 1
    p.hp += 1
  } else if (key === 'tianlei') this.trumpCdMult = 0.8

  this.pillStock[key] -= 1
  this.pillApplied.push(cfg.name)
  this.pillFlash = 2.6
  storage.set(PILL_KEY, JSON.stringify(this.pillStock))
  this.setPillQueue('')
}

setPillQueue(key) {
  this.pillQueue = PILLS[key] ? key : ''
  storage.set(PILLQ_KEY, this.pillQueue)
}

// 丹房卡片动作：先排队已炼好的，再炼新的（一颗丹药同局只生效一次，囤着没意义）
tapPill(key) {
  const cfg = PILLS[key]
  if (!cfg) return false
  if (this.pillQueue === key) return false
  if ((this.pillStock[key] || 0) > 0) {
    this.setPillQueue(key)
    this.sfx.powerup()
    return true
  }
  return this.brewPill(key)
}

