// 界面转场：状态切换后 180ms 淡入 + 1.02→1.0 回弹，避免硬切（EVALUATION P1-4）
const TRANSITION_MS = 180
let lastStatus = ''
let statusAt = 0

function drawUi(ctx, g, muted) {
  if (g.status !== lastStatus) {
    lastStatus = g.status
    statusAt = Date.now()
  }
  drawHud(ctx, g, muted)
  const el = Date.now() - statusAt
  if (el >= TRANSITION_MS) {
    drawScreen(ctx, g)
    return
  }
  // ease-out cubic：进场快、收尾软
  const k = el / TRANSITION_MS
  const e = 1 - (1 - k) * (1 - k) * (1 - k)
  ctx.save()
  ctx.globalAlpha = e
  ctx.translate(W / 2, H / 2)
  ctx.scale(1.02 - 0.02 * e, 1.02 - 0.02 * e)
  ctx.translate(-W / 2, -H / 2)
  drawScreen(ctx, g)
  ctx.restore()
}

// 当前状态对应的界面层（转场只作用于这一层，HUD 不动）
function drawScreen(ctx, g) {
  if (g.status === 'ready') drawReady(ctx, g)
  else if (g.status === 'paused') drawPaused(ctx)
  else if (g.status === 'over') drawOver(ctx, g)
  else if (g.status === 'upgrade') drawUpgrade(ctx, g)
  else if (g.status === 'trumpselect') drawTrumpSelect(ctx, g)
  else if (g.status === 'dungeonselect') drawDungeonSelect(ctx, g)
  else if (g.status === 'alchemy') drawAlchemy(ctx, g)
  else if (g.status === 'dungeonsettle') drawDungeonSettle(ctx, g)
}

