const cache = {}
const log = (s) => { document.getElementById('log').textContent += s + '\n' }

function norm(p) {
  const out = []
  p.split('/').forEach((s) => {
    if (!s || s === '.') return
    if (s === '..') out.pop()
    else out.push(s)
  })
  return out.join('/')
}
function dirname(p) {
  const i = p.lastIndexOf('/')
  return i < 0 ? '' : p.slice(0, i)
}
function fetchText(path) {
  const xhr = new XMLHttpRequest()
  xhr.open('GET', '/' + path, false)
  xhr.send(null)
  if (xhr.status !== 200) throw new Error('load fail ' + path + ' ' + xhr.status)
  return xhr.responseText
}
function load(path) {
  path = norm(path)
  if (cache[path]) return cache[path].exports
  const src = fetchText(path)
  const module = { exports: {} }
  cache[path] = module
  const fn = new Function('require', 'module', 'exports', src + '\n//# sourceURL=/' + path)
  fn((p) => load(norm(dirname(path) + '/' + p)), module, module.exports)
  return module.exports
}

