    for (let i = 0; i < 16; i++) {
      if (i === 6 || i === 7) continue
      const ang = (i / 16) * Math.PI * 2
      g.bullets.push({
        x: 240 + Math.cos(ang) * 60, y: 170 + Math.sin(ang) * 60,
        vx: Math.cos(ang) * 130, vy: Math.sin(ang) * 130 + 40,
        r: 5, damage: 1, from: 'enemy', kind: 'soul',
      })
    }
    addBullets(g, [{ x: 240, y: 470 }, { x: 240, y: 430 }])
  },
}

// ============ 5. 渲染并上传 ============
function post(name, dataUrl) {
  return new Promise((resolve) => {
    const xhr = new XMLHttpRequest()
    xhr.open('POST', '/save?name=' + encodeURIComponent(name), true)
    xhr.setRequestHeader('Content-Type', 'text/plain')
    xhr.onload = () => resolve(xhr.status === 200)
    xhr.onerror = () => resolve(false)
    xhr.send(dataUrl)
  })
}

async function run() {
  const grid = document.getElementById('grid')
  for (const name of Object.keys(SCENES)) {
    try {
      const g = mkEngine()
      SCENES[name](g)
      // 关闭开局无敌闪烁，保证截图里主角一定可见
      if (g.player) g.player.invincibleUntil = 0
      const cv = document.createElement('canvas')
      cv.width = WORLD.W
      cv.height = WORLD.H
      const ctx = cv.getContext('2d')
      ctx.setTransform(1, 0, 0, 1, 0, 0)
      ctx.fillStyle = '#070b18'
      ctx.fillRect(0, 0, cv.width, cv.height)
      render(ctx, g)
      drawUi(ctx, g, false)
      grid.appendChild(cv)
      const ok = await post(name, cv.toDataURL('image/png'))
      log((ok ? 'OK   ' : 'FAIL ') + name)
    } catch (err) {
      log('ERR  ' + name + ' :: ' + err.message)
    }
  }
  log('DONE')
  document.title = 'DONE'
}

run()
