  // Karplus-Strong 拨弦：噪声激励 + 短延迟反馈，古筝/琵琶质感
  _pluckBuf(freq) {
    const key = Math.round(freq)
    if (this.pluckBufs[key]) return this.pluckBufs[key]
    const ctx = this.ctx
    const sr = ctx.sampleRate
    const n = Math.max(2, Math.floor(sr / freq))
    const len = Math.floor(sr * 0.9)
    const buf = ctx.createBuffer(1, len, sr)
    const out = buf.getChannelData(0)
    const ring = new Float32Array(n)
    for (let i = 0; i < n; i++) ring[i] = Math.random() * 2 - 1
    let p = 0
    for (let i = 0; i < len; i++) {
      const cur = ring[p]
      out[i] = cur
      ring[p] = (cur + ring[(p + 1) % n]) * 0.5 * 0.996
      p = (p + 1) % n
