  }

  _layer(name, on, base) {
    const g = this.layers && this.layers[name]
    if (!g || !this.ctx) return
    g.gain.cancelScheduledValues(this.ctx.currentTime)
    g.gain.setTargetAtTime(on ? base : 0, this.ctx.currentTime, 0.25)
  }

  // scene: 'off' | 'menu' | 'battle' | 'boss'
  music(scene, chapterIdx) {
    if (scene === 'off') {
      this._stopMusic()
      return
    }
    if (!this.ensure()) return
    const sc = Math.max(0, Math.min(SCALES.length - 1, chapterIdx | 0))
    if (sc !== this.scale) this.scale = sc
    if (!this.timer) {
      this.step = 0
      this.nextTime = this.ctx.currentTime + 0.1
      this.timer = setInterval(() => this._tick(), 100)
    }
    if (scene !== this.scene) {
      this.scene = scene
      const battle = scene === 'battle' || scene === 'boss'
      this._layer('battle', battle, 0.12)
      this._layer('boss', scene === 'boss', 0.15)
    }
  }

  _stopMusic() {
    this.scene = 'off'
    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
    }
    this._layer('battle', false, 0.12)
    this._layer('boss', false, 0.15)
  }

  // 切后台 / 暂停：只压总音量，不停 oscillator（重启会有爆音）
  duck(on) {
    if (!this.master || !this.ctx) return
    this.master.gain.setTargetAtTime(on ? 0.18 : 0.75, this.ctx.currentTime, 0.15)
  }
}

module.exports = { SoundManager }

