10→let sent = 0
11→const onceFlags = {}
12→
13→function available() {
14→  return typeof tt !== 'undefined' && typeof tt.reportAnalytics === 'function'
15→}
16→
17→// 清洗参数：布尔转 0/1，其余非法类型丢弃
18→function clean(data) {
19→  const out = {}
20→  if (!data) return out
21→  for (const k in data) {
22→    const v = data[k]
23→    if (typeof v === 'number' && isFinite(v)) out[k] = Math.round(v * 100) / 100
24→    else if (typeof v === 'string') out[k] = v.slice(0, 60)
25→    else if (typeof v === 'boolean') out[k] = v ? 1 : 0
26→  }
27→  return out
28→}
29→
30→function send(name, data) {
31→  if (!name) return false
32→  try {
33→    if (!available()) return false
34→    tt.reportAnalytics(PREFIX + name, clean(data))
35→    sent += 1
36→    return true
37→  } catch (err) {
38→    return false
39→  }
40→}
41→
42→// 每个会话只报一次（如 app_launch）
43→function once(name, data) {
44→  if (onceFlags[name]) return false
45→  onceFlags[name] = true
46→  return send(name, data)
47→}
48→
49→// 局内计时：从开局到结算的秒数
50→function duration(startTs) {
51→  if (!startTs) return 0
52→  return Math.max(0, Math.round((Date.now() - startTs) / 1000))
53→}
54→
55→function count() {
56→  return sent
57→}
58→
59→module.exports = { send, once, duration, count, PREFIX }
