// 摘星 - 版本号同步工具
// 用法：node tools/setversion.js [1.5.0]
// 只改 src/version.js 的 VERSION 与各源文件第一行文件头，不碰其它内容
const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const VERSION_FILE = path.join(ROOT, 'src', 'version.js')
const HEADER_RE = /^\/\/ 摘星 v[\d.]+  \|  版权所有 \(c\) 2026  \|  保留所有权利$/

function files() {
  return [path.join(ROOT, 'game.js')].concat(
    fs.readdirSync(path.join(ROOT, 'src')).filter((f) => f.endsWith('.js')).map((f) => path.join(ROOT, 'src', f))
  )
}

function readVersion() {
  const m = fs.readFileSync(VERSION_FILE, 'utf8').match(/VERSION: '([\d.]+)'/)
  return m ? m[1] : ''
}

function apply(version) {
  if (!/^\d+\.\d+\.\d+$/.test(version)) throw new Error('版本号需形如 1.5.0')
  let n = 0
  for (const f of files()) {
    const src = fs.readFileSync(f, 'utf8')
    let out = src
    if (f === VERSION_FILE) out = out.replace(/VERSION: '[\d.]+'/, "VERSION: '" + version + "'")
    const header = '// 摘星 v' + version + '  |  版权所有 (c) 2026  |  保留所有权利'
    out = HEADER_RE.test(out.split('\n')[0]) ? out.replace(/^.*/, header) : header + '\n' + out
    if (out !== src) { fs.writeFileSync(f, out); n++ }
  }
  return n
}

if (require.main === module) {
  const v = process.argv[2] || readVersion()
  console.log('版本 ' + v + '：改动 ' + apply(v) + ' 个文件')
}

module.exports = { readVersion, apply }
```

