const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const VERSION_FILE = path.join(ROOT, 'src', 'version.js')
const HEADER_RE = /^\/\/ 摘星 v[\d.]+ {2}\| {2}版权所有 \(c\) 2026 {2}\| {2}保留所有权利/

function listFiles() {
  const dir = path.join(ROOT, 'src')
  return [path.join(ROOT, 'game.js')].concat(
    fs
      .readdirSync(dir)
      .filter((f) => f.endsWith('.js'))
      .sort()
      .map((f) => path.join(dir, f)),
  )
}

function readVersion() {
  const m = fs.readFileSync(VERSION_FILE, 'utf8').match(/VERSION: '([\d.]+)'/)
  return m ? m[1] : ''
}

function apply(version) {
  if (!/^\d+\.\d+\.\d+$/.test(version)) throw new Error('版本号需形如 1.5.0')
  const header = '// 摘星 v' + version + '  |  版权所有 (c) 2026  |  保留所有权利'
  let changed = 0
  for (const file of listFiles()) {
    const src = fs.readFileSync(file, 'utf8')
    let out = src
    if (file === VERSION_FILE) out = out.replace(/VERSION: '[\d.]+'/, "VERSION: '" + version + "'")
    const lines = out.split('\n')
    if (HEADER_RE.test(lines[0])) {
