  4→//
  5→// 三个概念必须分清，混淆会直接导致直玩方案下线：
  6→//   直玩预启动    抖音在推荐流后台预加载游戏，用户还没点进来 —— 不能弹窗、不算活跃
  7→//   直玩点击启动  用户点了「立即去玩」，收到 feedEnter 才是真实用户
  8→//   获客版        feed_game_channel = 2，全程禁止功能 / 提示 / 奖励弹窗
  9→
 10→const FEED_SCENE_SUFFIX = '3041' // scene 后四位为 3041 即推荐流直玩场景
 11→const REPORT_SCENE_ID = 7001 // 固定值：游戏加载完成、达到用户可交互状态
 12→const CHANNEL_RETURNING = 1 // 复访用户
 13→const CHANNEL_ACQUISITION = 2 // 获客用户
 14→const POPUP_GUARD_MS = 5000 // §4.2：进入游戏 5 秒内禁止弹窗
 15→
 16→// 启动参数：任何异常都退化为「普通启动」，不能因为取不到参数就白屏
 17→function readOptions() {
 18→  try {
 19→    if (typeof tt !== 'undefined' && typeof tt.getLaunchOptionsSync === 'function') {
 20→      return tt.getLaunchOptionsSync() || {}
 21→    }
 22→  } catch (err) {
 23→    /* 低版本或非抖音环境，按普通启动处理 */
 24→  }
 25→  return {}
 26→}
 27→
 28→const opt = readOptions()
 29→const query = opt.query || {}
 30→const scene = opt.scene === undefined || opt.scene === null ? '' : String(opt.scene)
 31→const channel = Number(query.feed_game_channel) || 0
 32→const isFeed = scene.length >= 4 && scene.slice(-4) === FEED_SCENE_SUFFIX
 33→
 34→// 用户是否已真实进入（feedEnter 或首次触摸）。预启动阶段恒为 false
 35→let entered = false
 36→let enteredAt = 0
 37→let readyReported = false
 38→let enterCb = null
 39→
 40→function markEntered(source) {
 41→  if (entered) return
 42→  entered = true
 43→  enteredAt = Date.now()
 44→  if (typeof enterCb === 'function') enterCb(source || 'unknown')
 45→}
 46→
 47→function onEnter(cb) {
 48→  if (typeof cb !== 'function') return
 49→  if (entered) {
 50→    cb('cached')
 51→    return
 52→  }
 53→  enterCb = cb
 54→}
 55→
 56→// §2.4 必接：不上报加载完成，游戏不会出现在推荐流里
 57→function reportReady() {
 58→  if (readyReported) return
 59→  readyReported = true
 60→  try {
 61→    if (typeof tt !== 'undefined' && typeof tt.reportScene === 'function') {
 62→      tt.reportScene({ sceneId: REPORT_SCENE_ID })
 63→    }
 64→  } catch (err) {
 65→    /* 非直玩环境或低版本，忽略 */
 66→  }
 67→}
