 69→// 预览流进入 / 退出监听。规则书写作 tt.feedStatusChange，官方文档为 tt.onFeedStatusChange，
 70→// 两个名字都兜住；都不可用时返回 false，由调用方降级为「首次触摸即算进入」
 71→function watchFeed(onExit) {
 72→  const api =
 73→    typeof tt === 'undefined'
 74→      ? null
 75→      : typeof tt.onFeedStatusChange === 'function'
 76→      ? tt.onFeedStatusChange
 77→      : typeof tt.feedStatusChange === 'function'
 78→      ? tt.feedStatusChange
 79→      : null
 80→  if (!api) return false
 81→
 82→  const handler = (res) => {
 83→    const type = res && res.type
 84→    if (type === 'feedEnter') {
 85→      markEntered('feed')
 86→    } else if (type === 'feedExit' && typeof onExit === 'function') {
 87→      onExit()
 88→    }
 89→  }
 90→  try {
 91→    api.call(tt, handler)
 92→    return true
 93→  } catch (err) {
 94→    return false
 95→  }
 96→}
 97→
 98→// §4.2：获客版全程禁弹窗；其余情况进入游戏 5 秒后才允许
 99→function popupAllowed(elapsedMs) {
100→  if (isFeed && channel === CHANNEL_ACQUISITION) return false
101→  return elapsedMs >= POPUP_GUARD_MS
102→}
103→
104→module.exports = {
105→  scene,
106→  query,
107→  channel,
108→  isFeed,
109→  isAcquisition: isFeed && channel === CHANNEL_ACQUISITION,
110→  isReturning: isFeed && channel === CHANNEL_RETURNING,
111→  get entered() {
112→    return entered
113→  },
114→  get enteredAt() {
115→    return enteredAt
116→  },
117→  markEntered,
118→  onEnter,
119→  reportReady,
120→  watchFeed,
121→  popupAllowed,
122→  POPUP_GUARD_MS,
123→}
